/* Exercise rules, separate from the page and audio player. */
(()=>{'use strict';
function create(source){
 const banks={match:new Map(source.characters.map(w=>[w.id,w])),dictation:new Map(source.words.map(w=>[w.id,w]))},pinyins=[...new Set(source.characters.map(w=>w.pinyin))];
 const scope=s=>['all','class',...Array.from({length:15},(_,i)=>String(i+1))].includes(String(s))?String(s):'all';
 const integer=(v,max=9)=>Math.min(max,Math.max(0,Math.trunc(Number(v)||0)));
 const shuffled=(list,random=Math.random)=>{list=[...list];for(let i=list.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[list[i],list[j]]=[list[j],list[i]];}return list;};
 function pool(kind,selection){return [...banks[kind].values()].filter(w=>selection==='all'||(selection==='class'?w.lessons.some(n=>n>=9):w.lessons.includes(Number(selection))));}
 function options(id,selected,seed){const correct=banks.match.get(id).pinyin;let hash=2166136261;for(const ch of id+':'+seed)hash=Math.imul(hash^ch.charCodeAt(0),16777619)>>>0;const random=()=>{hash=(Math.imul(hash,1664525)+1013904223)>>>0;return hash/4294967296;};const base=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');let others=shuffled(pinyins.filter(p=>p!==correct),random);others.sort((a,b)=>Number(base(b)===base(correct))-Number(base(a)===base(correct)));const chosen=[correct,...others.slice(0,3)];if(selected&&pinyins.includes(selected)&&!chosen.includes(selected))chosen[3]=selected;return shuffled(chosen,random);}
 function round(raw,defaults={}){if(!raw||!banks[raw.kind]||!Array.isArray(raw.ids)||raw.ids.length!==10||new Set(raw.ids).size!==10||!raw.ids.every(id=>banks[raw.kind].has(id)))return null;
 const r={kind:raw.kind,ids:[...raw.ids],phase:'active',scope:scope(raw.scope??defaults.scope),filter:(raw.filter??defaults.filter)==='mistakes'?'mistakes':'all',index:integer(raw.index),reviewIndex:integer(raw.reviewIndex),heard:Array.from({length:10},(_,i)=>raw.heard?.[i]===true),answers:{},marks:{},counted:false,created:Number(raw.created)||Date.now(),targeted:integer(raw.targeted,10)};
 for(let i=0;i<10;i++){if(r.kind==='match'&&typeof raw.answers?.[i]==='string'&&pinyins.includes(raw.answers[i]))r.answers[i]=raw.answers[i];if(typeof raw.marks?.[i]==='boolean'&&(r.kind==='dictation'||r.answers[i]))r.marks[i]=r.kind==='match'?r.answers[i]===banks.match.get(r.ids[i]).pinyin:raw.marks[i];}
 const allMarked=Object.keys(r.marks).length===10;
 if(r.kind==='match'){if(raw.phase==='complete'&&allMarked){r.phase='complete';r.counted=raw.counted===true;}}
 else{const first=r.heard.indexOf(false);if(first>=0){r.index=Math.min(r.index,first);}else if(raw.phase==='review'||raw.phase==='complete'){r.phase=raw.phase==='complete'&&allMarked?'complete':'review';r.counted=r.phase==='complete'&&raw.counted===true;if(raw.reviewIndex===undefined){const next=Array.from({length:10},(_,i)=>i).find(i=>typeof r.marks[i]!=='boolean');r.reviewIndex=next??0;}}}
 return r;}
 function clean(raw){if(!raw||raw.version!==1)throw Error('Invalid practice backup');const out={version:1,kind:raw.kind==='dictation'?'dictation':'match',scope:scope(raw.scope),filter:raw.filter==='mistakes'?'mistakes':'all',speed:[.65,.8,1].includes(Number(raw.speed))?Number(raw.speed):.8,preferences:{},round:null,parked:{},stats:{},history:[]};
 for(const k of ['match','dictation']){const p=raw.preferences?.[k]||{};out.preferences[k]={scope:scope(p.scope??(raw.kind===k?raw.scope:'all')),filter:(p.filter??(raw.kind===k?raw.filter:'all'))==='mistakes'?'mistakes':'all'};const parked=round(raw.parked?.[k],out.preferences[k]);if(parked?.kind===k)out.parked[k]=parked;}
 out.round=round(raw.round,out);if(out.round){out.kind=out.round.kind;out.scope=out.round.scope;out.filter=out.round.filter;delete out.parked[out.kind];}out.preferences[out.kind]={scope:out.scope,filter:out.filter};
 for(const [key,s]of Object.entries(raw.stats||{})){const split=key.indexOf(':'),kind=key.slice(0,split),id=key.slice(split+1);if(!banks[kind]?.has(id)||!s||typeof s!=='object')continue;const attempts=integer(s.attempts,1e7);out.stats[key]={attempts,correct:Math.min(attempts,integer(s.correct,1e7)),streak:integer(s.streak,4),due:Number(s.due)||0,lastCorrect:s.lastCorrect===true};}
 out.history=Array.isArray(raw.history)?raw.history.filter(h=>h&&banks[h.kind]&&Number.isFinite(h.time)&&Number.isFinite(h.score)).slice(-100).map(h=>({...h,score:integer(h.score,10),total:10})):[];return out;}
 function switchKind(data,kind){if(!banks[kind]||data.kind===kind)return;data.preferences[data.kind]={scope:data.scope,filter:data.filter};if(data.round)data.parked[data.kind]=data.round;data.kind=kind;data.round=data.parked[kind]||null;delete data.parked[kind];const p=data.round||data.preferences[kind];data.scope=p.scope;data.filter=p.filter;}
 function sample(data,random=Math.random){const available=pool(data.kind,data.scope),previous=new Set(data.round?.ids||[]),now=Date.now();const priority=w=>{const stat=data.stats[data.kind+':'+w.id];return (previous.has(w.id)?4:0)+(!stat?0:stat.due<=now?1:2);};const missed=shuffled(available.filter(w=>data.stats[data.kind+':'+w.id]?.lastCorrect===false),random),normal=shuffled(available,random).sort((a,b)=>priority(a)-priority(b));const result=[],seen=new Set();let targeted=0;
 for(const w of data.filter==='mistakes'?[...missed,...normal]:normal){if(seen.has(w.text))continue;seen.add(w.text);result.push(w);if(data.filter==='mistakes'&&missed.some(m=>m.id===w.id))targeted++;if(result.length===10)break;}return {items:result,targeted,missed:missed.length};}
 function start(data,random=Math.random){const picked=sample(data,random);if(picked.items.length!==10)throw Error('Choose a lesson selection with at least ten different items.');if(data.filter==='mistakes'&&!picked.missed)throw Error('No missed items yet. Choose All items to start.');return {kind:data.kind,ids:picked.items.map(w=>w.id),phase:'active',scope:data.scope,filter:data.filter,index:0,reviewIndex:0,heard:Array(10).fill(false),answers:{},marks:{},counted:false,created:Date.now(),targeted:picked.targeted};}
 function checkMatch(r){if(r.kind!=='match'||r.phase!=='active'||typeof r.marks[r.index]==='boolean')return false;const answer=r.answers[r.index];if(!options(r.ids[r.index],answer,r.created).includes(answer))return false;r.marks[r.index]=answer===banks.match.get(r.ids[r.index]).pinyin;return true;}
 function canNext(r){return r.kind==='match'?typeof r.marks[r.index]==='boolean':r.heard[r.index]===true;}
 function reveal(r){if(r.kind!=='dictation'||r.phase!=='active'||!r.heard.every(Boolean))return false;r.phase='review';r.reviewIndex=0;return true;}
 function finish(data){const r=data.round;if(!r||r.counted||Object.keys(r.marks).length!==10||(r.kind==='dictation'&&!r.heard.every(Boolean)))return false;for(let i=0;i<10;i++){const key=r.kind+':'+r.ids[i],s=data.stats[key]||{attempts:0,correct:0,streak:0};s.attempts++;s.correct+=Number(r.marks[i]);s.streak=r.marks[i]?Math.min(4,s.streak+1):0;s.lastCorrect=r.marks[i];s.due=Date.now()+(r.marks[i]?[1,3,7,14][s.streak-1]*86400000:600000);data.stats[key]=s;}r.counted=true;r.phase='complete';data.history.push({kind:r.kind,time:Date.now(),score:Object.values(r.marks).filter(Boolean).length,total:10});data.history=data.history.slice(-100);return true;}
 return {banks,pool,options,round,clean,switchKind,sample,start,checkMatch,canNext,reveal,finish};
}
window.HanziExerciseCore={create};
})();
